export function swipeDirection(start,end,{threshold=32,maxDuration=900}={}){const dx=end.x-start.x,dy=end.y-start.y;if(end.time-start.time>maxDuration||Math.max(Math.abs(dx),Math.abs(dy))<threshold)return null;return Math.abs(dx)>Math.abs(dy)?dx>0?'right':'left':dy>0?'down':'up'}
export function bindSwipes(element,onSwipe,enabled=()=>true){let start=null;const abort=new AbortController(),options={signal:abort.signal};element.addEventListener('pointerdown',e=>{if(!enabled()||e.button>0)return;start={x:e.clientX,y:e.clientY,time:performance.now(),id:e.pointerId};element.setPointerCapture(e.pointerId)},options);element.addEventListener('pointerup',e=>{if(!start||e.pointerId!==start.id)return;const direction=swipeDirection(start,{x:e.clientX,y:e.clientY,time:performance.now()});start=null;if(enabled()&&direction)onSwipe(direction)},options);element.addEventListener('pointercancel',()=>start=null,options);return()=>abort.abort()}
